import { ReviewRecord, buildReviewPage } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  assert(Object.is(actual, expected), `${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function expectThrows(fn: () => unknown, ctor: ErrorConstructor, message: string): void {
  let error: unknown;
  try { fn(); } catch (caught) { error = caught; }
  assert(error instanceof ctor, message);
}

const records: ReviewRecord[] = [
  { contributor: " Alice ", document: "Second", submittedOn: "2026-02-02", score: null },
  { contributor: "Bob", document: "First", submittedOn: "2026-01-01", score: 0 },
  { contributor: "Cara", document: "Same date", submittedOn: "2026-01-01", score: 100 },
];
const originalOrder = records.slice();
const page = buildReviewPage("reviewer", records);
equal(page.title, "Pending Reviews", "title is fixed");
equal(page.rows.map((row) => row.contributor).join(","), "Bob,Cara, Alice ", "rows sort stably by date");
equal(page.rows[0].status, "scored", "zero score is scored");
equal(page.rows[1].status, "scored", "upper boundary score is scored");
equal(page.rows[2].status, "pending", "null score is pending");
equal(page.rows[2].contributor, " Alice ", "returned strings are not trimmed");
assert(records[0] === originalOrder[0] && records[1] === originalOrder[1] && records[2] === originalOrder[2], "input array is not sorted or replaced");
assert(page.rows.every((row) => !records.some((record) => record === row)), "rows do not alias input records");

const again = buildReviewPage("reviewer", records);
assert(page !== again, "successful calls return fresh pages");
assert(page.rows !== again.rows, "successful calls return fresh row arrays");
assert(page.rows[0] !== again.rows[0], "successful calls return fresh row objects");
(page.rows[0] as { contributor: string }).contributor = "changed";
equal(records[1].contributor, "Bob", "row mutation does not affect input");
equal(again.rows[0].contributor, "Bob", "rows from calls do not alias");

const empty1 = buildReviewPage("reviewer", []);
const empty2 = buildReviewPage("reviewer", []);
equal(empty1.rows.length, 0, "empty input succeeds");
assert(empty1.rows !== empty2.rows, "empty row arrays are fresh");

for (const role of ["Reviewer", " reviewer", "reviewer ", "", "admin"]) {
  expectThrows(() => buildReviewPage(role, [{ contributor: "", document: "", submittedOn: "", score: -1 }]), Error, "authorization is checked before records");
}
for (const bad of [
  { contributor: " \t", document: "d", submittedOn: "s", score: null },
  { contributor: "c", document: "\n", submittedOn: "s", score: null },
  { contributor: "c", document: "d", submittedOn: "  ", score: null },
] as ReviewRecord[]) {
  expectThrows(() => buildReviewPage("reviewer", [bad]), TypeError, "blank required string throws TypeError");
}
for (const score of [-1, 101, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY]) {
  expectThrows(() => buildReviewPage("reviewer", [{ contributor: "c", document: "d", submittedOn: "s", score }]), RangeError, "invalid score throws RangeError");
}
const boundaries = buildReviewPage("reviewer", [
  { contributor: "a", document: "d", submittedOn: "a", score: 0 },
  { contributor: "b", document: "d", submittedOn: "b", score: 100 },
]);
equal(boundaries.rows.length, 2, "score boundaries are accepted");

